        ("-d, --domain", "Target domain.", "dns mode."),
        ("-w, --wordlist", "Wordlist file.", "Always."),
        ("-t, --threads", "Number of parallel workers (default 10).", "Speed."),
        ("-x, --extensions", "File extensions to try.", "Finding php, txt, bak."),
        ("-s, --status-codes", "Status codes that count as found.", "Custom hit rules."),
        ("-b, --status-codes-blacklist", "Status codes to ignore (default 404).", "Clearing noise."),
        ("-c, --cookies", "Cookies to send.", "Logged-in scans."),
        ("-H, --headers", "Extra headers.", "Custom headers or tokens."),
        ("-U / -P, --username / --password", "HTTP basic auth.", "Protected sites."),
        ("-a, --useragent", "Set the user agent.", "Servers that block the default."),
        ("-k, --no-tls-validation", "Skip TLS certificate checks.", "Self-signed lab certificates."),
        ("-r, --follow-redirect", "Follow redirects.", "Redirected paths."),
        ("-e, --expanded", "Print the full URL.", "Easy to copy."),
        ("-n, --no-status", "Do not print status codes.", "Short output."),
        ("-l, --include-length", "Print response length.", "Spotting odd sizes."),
        ("--exclude-length", "Hide responses of these lengths.", "Wildcard pages."),
        ("--wildcard", "Continue even if the server answers everything (dns).", "Wildcard DNS."),
        ("--append-domain", "Append the domain to each word (vhost).", "Right Host headers."),
        ("--timeout", "HTTP timeout.", "Slow servers."),
        ("--delay", "Delay between requests.", "Avoiding blocking."),
        ("--retry / --retry-attempts", "Retry failed requests.", "Flaky links."),
        ("-o, --output", "Write results to a file.", "Saving evidence."),
        ("-q, --quiet", "Do not print the banner.", "Scripts."),
        ("-z, --no-progress", "Do not print progress.", "Clean logs."),
